from pathlib import Path
import base64, json, os, sys, subprocess, runpy
install=subprocess.run([sys.executable,'-m','pip','install','--upgrade','pylibcugraph-cu12==26.10.0','zstandard'],capture_output=True,text=True,timeout=900)
Path('/kaggle/working/public_reference_install.log').write_text(install.stdout+install.stderr)
if install.returncode: raise RuntimeError('Vendor install failed')
folder=Path('/kaggle/working/sinha_public_reference_modules');folder.mkdir(exist_ok=True)
files=json.loads('{"benchmark.py": "", "benchmark_cuda.py": "", "benchmark_sparse.py": "", "benchmark_upgrades.py": "", "c2fuse.py": "", "chebyshev_ppr.py": "", "cuda_c2fuse.py": "", "example_sensitivity_gpu.py": "", "example_sparse.py": "", "example_upgrades.py": "", "fast_bounds.py": "", "local_c2fuse.py": "", "ppr_certificate.py": "", "sensitivity_c2fuse.py": "", "sparse_c2fuse.py": "", "test_c2fuse.py": "", "test_cuda.py": "", "test_graph_upgrades.py": "", "test_sensitivity.py": "", "test_sparse_c2fuse.py": "", "sinha_industry_bench.py": "", "sinha_public_reference_bench.py": "", "SinhaArcadePR.java": "", "SinhaArcadePR.class": ""}')
for name,body in files.items(): (folder/name).write_bytes(base64.b64decode(body))
sys.path.insert(0,str(folder));os.chdir(folder)
runpy.run_path(str(folder/'sinha_public_reference_bench.py'),run_name='__main__')
